<script setup lang="ts">
import {clientThemeStyle} from '../../lib/client-theme'
import {ref,computed,reactive,watch,onBeforeUnmount} from 'vue'
import {onLoad} from '@dcloudio/uni-app'
import ClientNavigation from '../../components/ClientNavigation.vue'
import ClientPasswordInput from '../../components/ClientPasswordInput.vue'
import {api,loginPassword,loginSms,exchangeOfficial,startOfficialLogin,loginWechat,message,isH5} from '../../lib/api'
import {h5PagePath} from '@qicore/application-sdk/browser/h5-routes.mjs'
import {frameworkAsset} from '@qicore/application-sdk/browser/decoration-framework.mjs'
import {runtimeConfig,clientImageUrl} from '../../lib/runtime-config'
import {consumerAuthAppearance} from '@qicore/application-sdk/browser/consumer-auth-appearance.mjs'
type Mode='wechat'|'password'|'sms'|'register'|'reset'
const runtime=reactive(runtimeConfig()) as any,mode=ref<Mode>(isH5?'password':'wechat'),account=ref(''),phone=ref(''),password=ref(''),confirmation=ref(''),code=ref(''),action=ref(''),sending=ref(false),error=ref(''),notice=ref(''),returnPath=ref('/'),agreed=ref(false),policies=ref<{kind:string;title:string;version:number}[]>(runtime.policies||[])
const register=computed(()=>mode.value==='register'),isLogin=computed(()=>['wechat','password','sms'].includes(mode.value)),locked=computed(()=>!!action.value||sending.value),wechat=computed(()=>isH5&&/MicroMessenger/i.test(navigator.userAgent)),asset=(name:string)=>(isH5?'/h5-assets':'')+frameworkAsset(name,true),authAsset=(name:string)=>(isH5?'/h5-assets':'')+'/static/auth/'+name
const appearance=computed(()=>consumerAuthAppearance(runtime.registration?.appearance)),settingsFailed=ref(false)
async function loadSettings(force=false){if(runtime.registration&&!force&&!settingsFailed.value)return true;if(action.value)return false;const initial=!runtime.registration;action.value='settings';error.value='';try{const value=await api<any>('/consumer/auth/settings?tenantId='+encodeURIComponent(runtime.tenantId)+'&applicationKey='+encodeURIComponent(runtime.applicationKey));if(!alive)return false;const current=runtimeConfig();if(current.tenantId!==runtime.tenantId||current.applicationKey!==runtime.applicationKey)throw Error('站点已变化，请重新打开登录页面');if(['terms','privacy'].some(kind=>policies.value.find(p=>p.kind===kind)?.version!==value.policies?.find((p:any)=>p.kind===kind)?.version))agreed.value=false;Object.assign(runtime,value);policies.value=value.policies||[];settingsFailed.value=false;if(initial&&isH5)mode.value=runtime.registration?.passwordLoginEnabled?'password':'sms';return true}catch(e){if(alive){error.value=message(e);settingsFailed.value=true}return false}finally{if(alive)action.value=''}}
let alive=true
const siteScope=(value:any)=>JSON.stringify([value.apiBase,value.tenantId,value.applicationKey]),loginScope=siteScope(runtime),currentPage=()=>alive&&siteScope(runtimeConfig())===loginScope
type SendAttempt={id:string;deadline:number;unknown:boolean}
const sendAttempts=reactive(new Map<string,SendAttempt>()),clock=ref(Date.now()),sendPurpose=computed(()=>mode.value==='reset'?'reset':'login'),sendKey=computed(()=>JSON.stringify([loginScope,phone.value,sendPurpose.value]))
const remaining=computed(()=>Math.max(0,Math.ceil(((sendAttempts.get(sendKey.value)?.deadline||0)-clock.value)/1000))),unknown=computed(()=>sendAttempts.get(sendKey.value)?.unknown===true)
const timer=setInterval(()=>{clock.value=Date.now()},1000)
watch([phone,sendPurpose],()=>{code.value='';error.value='';notice.value=''},{flush:'sync'})
onBeforeUnmount(()=>{alive=false;clearInterval(timer);sendAttempts.clear();password.value='';confirmation.value='';code.value=''})
function back(path:string){if(!isH5){try{if(/^%2f/i.test(path))path=decodeURIComponent(path)}catch{return '/pages/home/index'}return /^\/pages\/[a-zA-Z0-9_-]+\/[a-zA-Z0-9_-]+(?:\?[^#\s]*)?$/.test(path)&&!path.startsWith('/pages/login/')?path:'/pages/home/index'}if(/^%2f/i.test(path)){try{path=decodeURIComponent(path)}catch{return '/'}}const [pathname,...query]=path.split('?'),target=h5PagePath(pathname||'/');return target!=='/login'&&Object.hasOwn(runtime.titles||{},target)?target+(query.length?'?'+query.join('?'):''):'/'}
function changeMode(next:Mode|boolean){if(locked.value)return;mode.value=typeof next==='boolean'?(next?'register':'password'):next;password.value='';confirmation.value='';code.value='';error.value='';notice.value=mode.value==='sms'&&!runtime.registration?.smsLoginEnabled?'本站尚未开启手机号验证码登录。':''}
function consent(){if(!agreed.value)throw Error('请先阅读并同意用户协议和隐私政策');if(policies.value.length<2)throw Error('本站用户协议和隐私政策尚未配置完整，请联系管理员');return policies.value.length?Object.fromEntries(policies.value.map(p=>[p.kind,p.version])):undefined}
async function failed(e:any,operation:'auth'|'reset'|'send'='auth'){if(!currentPage())return;error.value=operation==='send'&&['NETWORK_UNKNOWN','SMS_RESULT_UNKNOWN'].includes(e?.code)?'验证码发送结果未确认，请查询原发送状态':e?.code==='NETWORK_UNKNOWN'?(operation==='reset'?'重置结果暂未确认，请先尝试使用新密码登录':'网络暂不可用，请稍后重试'):message(e);if(e?.code==='POLICY_CONSENT_REQUIRED'){agreed.value=false;action.value='';sending.value=false;if(await loadSettings(true))notice.value='协议已更新，请阅读后重新勾选同意'}}
async function submit(){if(mode.value==='wechat')return nativeLogin();if(locked.value)return;if(!currentPage()){error.value='站点已变化，请重新打开登录页面';return}const operation=mode.value==='reset'?'reset':'auth';error.value='';notice.value='';try{
 if(isLogin.value||register.value)consent();
 if(['password','register'].includes(mode.value)&&!account.value.trim())throw Error('请输入账号');
 if(['password','register'].includes(mode.value)&&!password.value)throw Error('请输入密码');
 if(['register','reset'].includes(mode.value)&&(password.value.length<6||password.value.length>128))throw Error('密码须为 6–128 个字符');
 if(['register','reset'].includes(mode.value)&&password.value!==confirmation.value)throw Error('两次输入的密码不一致');
 if(['sms','reset'].includes(mode.value)&&!/^1[3-9]\d{9}$/.test(phone.value))throw Error('手机号须为有效的 11 位手机号');
 if(['sms','reset'].includes(mode.value)&&!/^\d{6}$/.test(code.value))throw Error('验证码须为 6 位数字');
 action.value=mode.value;
 if(mode.value==='reset'){const result=await api<{account:string}>('/consumer/auth/sms/reset','POST',{tenantId:runtime.tenantId,applicationKey:runtime.applicationKey,phone:phone.value,code:code.value,password:password.value});if(!currentPage())return;action.value='';changeMode('password');account.value=result.account||account.value;notice.value='密码已重置，请重新登录';return}
 if(mode.value==='sms')await loginSms(phone.value,code.value,consent());else await loginPassword(account.value.trim(),password.value,register.value,consent());
 if(currentPage()){uni.reLaunch({url:back(returnPath.value)})}
 }catch(e){await failed(e,operation)}finally{if(alive)action.value=''}}
async function sendCode(){
 if(locked.value||remaining.value>0&&!unknown.value)return
 if(!currentPage()){error.value='站点已变化，请重新打开登录页面';return}
 const key=sendKey.value,purpose=sendPurpose.value,targetPhone=phone.value;let attempt:SendAttempt|undefined
 error.value='';notice.value=''
 try{
  if(!/^1[3-9]\d{9}$/.test(targetPhone))throw Error('请输入有效手机号')
  if(purpose==='login'){if(!runtime.registration?.smsLoginEnabled)throw Error('本站尚未开启手机号验证码登录');consent()}
  const saved=sendAttempts.get(key)
  attempt=saved?.unknown?saved:{id:'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g,c=>{const n=Math.random()*16|0;return(c==='x'?n:(n&3)|8).toString(16)}),deadline:0,unknown:false}
  sendAttempts.set(key,attempt);sending.value=true
  const result=await api<{accepted:boolean;retryAfterSeconds:number}>('/consumer/auth/sms/send','POST',{tenantId:runtime.tenantId,applicationKey:runtime.applicationKey,phone:targetPhone,purpose,requestId:attempt.id,...(purpose==='login'?{consent:consent()}: {})})
  if(!currentPage())return
  if(result?.accepted!==true||!Number.isSafeInteger(result.retryAfterSeconds)||result.retryAfterSeconds<0)throw Object.assign(Error('验证码发送结果未确认'),{code:'SMS_RESULT_UNKNOWN'})
  clock.value=Date.now();sendAttempts.set(key,{id:'',deadline:clock.value+result.retryAfterSeconds*1000,unknown:false})
  if(key===sendKey.value)notice.value='验证码已发送，请查看手机'
 }catch(e:any){
  if(!currentPage())return
  if(attempt){if(attempt.unknown||['NETWORK_UNKNOWN','SMS_RESULT_UNKNOWN'].includes(e?.code))sendAttempts.set(key,{...attempt,unknown:true});else sendAttempts.delete(key)}
  if(key===sendKey.value)await failed(e,'send')
 }finally{if(alive)sending.value=false}
}
async function official(){if(locked.value)return;notice.value='';if(!runtime.officialLogin){notice.value='本站尚未配置微信登录，请联系管理员';return}if(!wechat.value){notice.value='请在微信中打开本站后使用微信登录';return}try{const accepted=consent();action.value='official';await startOfficialLogin(back(returnPath.value),accepted)}catch(e){await failed(e);action.value=''}}
async function nativeLogin(){if(isH5||locked.value||!currentPage())return;error.value='';notice.value='';try{const accepted=consent();action.value='wechat';await loginWechat(accepted);if(currentPage())uni.reLaunch({url:back(returnPath.value)})}catch(e){await failed(e)}finally{if(alive)action.value=''}}
function home(){uni.reLaunch({url:'/pages/home/index'})}
function toggleAgreement(){if(locked.value)return;agreed.value=!agreed.value;if(policies.value.length<2)notice.value='本站用户协议和隐私政策尚未配置完整，请联系管理员'}
function policy(kind:string){if(locked.value||!['terms','privacy'].includes(kind))return;const versions=policies.value.filter(p=>['terms','privacy'].includes(p.kind)&&Number.isSafeInteger(p.version)&&p.version>0).map(p=>p.kind+'Version='+p.version);uni.navigateTo({url:'/pages/policy/index?kind='+kind+(versions.length?'&'+versions.join('&'):'')})}
onLoad(async options=>{returnPath.value=back(String(options?.returnPath||'/'));if(!await loadSettings())return;if(isH5&&!runtime.registration?.passwordLoginEnabled)mode.value='sms';if(isH5&&options?.ticket){action.value='official';try{const path=await exchangeOfficial(String(options.ticket));if(alive){uni.reLaunch({url:back(path)})}}catch(e){await failed(e)}finally{if(alive)action.value=''}}})
</script>
<template><page-meta :page-style="clientThemeStyle"/>
<!-- #ifdef MP-WEIXIN -->
<scroll-view class="client-page-scroll" scroll-y enhanced :show-scrollbar="false">
<!-- #endif --><ClientNavigation v-if="!isH5" title="登录"/><view class="auth-page">
 <view class="auth-hero"><image class="auth-hero-image" :src="clientImageUrl(appearance.image)||asset('intro.png')" mode="aspectFill" aria-hidden="true"/><view class="auth-brand">{{appearance.brand||runtime.siteName||'QiCore'}}</view><view class="auth-welcome">{{mode==='reset'?'找回密码':register?appearance.registerTitle:appearance.loginTitle}}</view><view class="auth-description">{{mode==='reset'?'验证已绑定的手机号，设置新密码':register?appearance.registerDescription:appearance.loginDescription}}</view></view>
 <view class="auth-card">
  <view v-if="isLogin&&mode!=='wechat'" class="auth-tabs" role="tablist" aria-label="登录方式"><button v-if="runtime.registration?.passwordLoginEnabled" class="auth-tab" :class="{selected:mode==='password'}" role="tab" :aria-selected="mode==='password'" :disabled="locked" @click="changeMode('password')">账号登录</button><button v-if="runtime.registration?.smsLoginEnabled" class="auth-tab" :class="{selected:mode==='sms'}" role="tab" :aria-selected="mode==='sms'" :disabled="locked" @click="changeMode('sms')">验证码登录</button></view>
  <view v-else-if="!isLogin" class="auth-card-heading"><text>{{register?'注册账号':'找回密码'}}</text><button role="button" :disabled="locked" @click="changeMode(isH5?'password':'wechat')">返回登录</button></view>
  <template v-if="mode!=='wechat'">
