  <template v-if="mode==='sms'||mode==='reset'"><view class="auth-field"><image class="auth-field-icon" :src="asset('icons/phone.svg')" mode="aspectFit"/><input class="auth-input" aria-label="手机号" v-model="phone" type="number" :maxlength="11" placeholder="请输入手机号" :disabled="locked"/></view><view class="auth-field"><image class="auth-field-icon" :src="asset('icons/shield-check.svg')" mode="aspectFit"/><input class="auth-input" aria-label="验证码" v-model="code" type="number" :maxlength="6" placeholder="请输入验证码" :disabled="locked"/><button role="button" class="auth-code-button" :loading="sending" :aria-disabled="locked||remaining>0&&!unknown" :disabled="locked||remaining>0&&!unknown" @click="sendCode">{{unknown?'查询发送状态':remaining>0?remaining+'秒后重发':'获取验证码'}}</button></view></template>
  <view v-if="mode!=='sms'" class="auth-field"><image class="auth-field-icon" :src="asset('icons/lock-keyhole.svg')" mode="aspectFit"/><ClientPasswordInput v-model="password" label="密码" :placeholder="isLogin?'请输入密码':'设置密码，6–128 个字符'" :disabled="locked" :autocomplete="isLogin?'current-password':'new-password'" @confirm="isLogin&&submit()"/></view>
  <view v-if="register||mode==='reset'" class="auth-field"><image class="auth-field-icon" :src="asset('icons/lock-keyhole.svg')" mode="aspectFit"/><ClientPasswordInput v-model="confirmation" label="确认密码" placeholder="再次输入密码" :disabled="locked" autocomplete="new-password" @confirm="submit"/></view>
  </template><view v-if="error" class="auth-error" role="alert">{{error}}</view><view v-if="notice" class="auth-hint" role="status">{{notice}}</view>
  <button v-if="settingsFailed" role="button" class="auth-submit" :loading="action==='settings'" :disabled="locked" @click="loadSettings()">重新加载登录设置</button>
  <view v-else-if="action==='settings'" class="auth-hint" role="status">正在读取登录设置…</view>
  <button v-else role="button" class="auth-submit" :loading="['password','sms','register','reset','wechat'].includes(action)" :disabled="locked" @click="submit">{{mode==='wechat'?'一键登录':register?'注册并登录':mode==='reset'?'重置密码':'登录'}}</button>
