  <template v-if="!isH5&&mode==='wechat'&&(runtime.registration?.passwordLoginEnabled||runtime.registration?.smsLoginEnabled)"><view class="auth-other"><view/><text>其他登录方式</text><view/></view><view class="auth-links auth-alternatives"><button v-if="runtime.registration?.passwordLoginEnabled" role="button" :disabled="locked" @click="changeMode('password')">账号密码登录</button><button v-if="runtime.registration?.smsLoginEnabled" role="button" :disabled="locked" @click="changeMode('sms')">手机验证码登录</button></view></template>
  <template v-else-if="isLogin&&mode!=='wechat'"><view class="auth-other"><view/><text>其他登录方式</text><view/></view><button role="button" class="wechat-entry" :loading="action==='official'" :disabled="locked" @click="isH5?official():changeMode('wechat')"><view class="wechat-circle"><image :src="authAsset('wechat.png')" mode="aspectFit"/></view><text>{{isH5?'微信登录':'一键登录'}}</text></button></template>
  <view v-if="isLogin||register" class="auth-agreement"><button role="checkbox" class="agree-toggle" :aria-checked="agreed" aria-label="同意用户协议和隐私政策" :disabled="locked" @click="toggleAgreement"><view class="agree-check" :class="{checked:agreed}"><text v-if="agreed">✓</text></view></button><view class="agreement-copy"><text>我已阅读并同意</text><button role="button" @click="policy('terms')">《用户协议》</button><text>和</text><button role="button" @click="policy('privacy')">《隐私政策》</button></view></view>
 </view><button role="button" class="auth-home" :disabled="locked" @click="home">暂不登录，先逛逛<image :src="asset('icons/chevron-right.svg')" mode="aspectFit"/></button>
</view>
<!-- #ifdef MP-WEIXIN -->
</scroll-view>
<!-- #endif -->
</template>
<style scoped>
