}.auth-field-icon{width:36rpx;height:36rpx;flex-shrink:0;opacity:.55}.auth-input{box-sizing:border-box;flex:1;min-width:0;width:0;height:96rpx;padding:0;border:0;border-radius:0;background:transparent;font-size:28rpx;color:var(--client-text, #1e293b)}.auth-password-toggle{flex-shrink:0;min-width:64rpx;padding:16rpx 0;background:transparent;color:#64748b;font-size:24rpx!important;white-space:nowrap}.auth-submit{display:flex;align-items:center;justify-content:center;width:100%;min-height:96rpx;margin-top:34rpx!important;border-radius:16rpx;background:var(--client-primary, #2563eb);color:#fff;font-size:30rpx!important;font-weight:600!important;letter-spacing:2rpx}.auth-submit[disabled]{background:var(--client-primary-disabled, #dce7fa);color:#fff;opacity:1}.auth-error{margin:8rpx 0 22rpx;padding:18rpx 22rpx;border-radius:12rpx;background:#fff2f2;color:#be4545;font-size:24rpx;line-height:1.6}.auth-other{display:flex;align-items:center;gap:20rpx;margin:40rpx 0 26rpx;font-size:23rpx;color:#94a0b0}.auth-other>view{flex:1;height:1rpx;background:#edf0f5}.auth-wechat{display:flex;align-items:center;justify-content:center;min-height:88rpx;width:100%;background:#eef7f1;color:#268751;border-radius:16rpx;font-size:28rpx!important}.auth-hint{color:#8490a0;font-size:24rpx;line-height:1.7;margin-top:20rpx}.auth-home{display:flex;align-items:center;justify-content:center;gap:6rpx;margin:32rpx auto 0!important;padding:14rpx 20rpx;background:transparent;font-size:25rpx!important;color:#8190a5}.auth-home image{width:28rpx;height:28rpx;opacity:.45}
</style>

